                                    (if (@typeInfo(@TypeOf(prop)) == .@"enum") @intFromEnum(prop) else prop.value) = p.newExpr(E.Number{ .value = 0.0 }, (if (@typeInfo(@TypeOf(prop)) == .@"enum") @intFromEnum(prop) else prop.value).?.loc);
                                }
                            }
                        }
                        properties_slice[cp_cast_int(usize, end)] = prop;
                        end = (end + 1);
                    }
                    expr.data.e_object.properties = G.Property.List.fromBorrowedSliceDangerous(properties_slice[0..end]);
                    return expr;
                }
            }
            var result = Expr.init(E.Missing, E.Missing, expr.loc);
            _ = &result;
            for (cp_iter_slice(properties_slice)) |prop| {
                _ = &prop;
                if (prop.flags.contains(.is_computed)) {
                    result = result.joinWithComma(p.newExpr(E.Binary{ .op = .bin_add, .left = prop.key.?, .right = p.newExpr(E.String, prop.key.?.loc) }, prop.key.?.loc), p.allocator);
                }
                result = result.joinWithComma(((SideEffects.simplifyUnusedExpr(p, (if (@typeInfo(@TypeOf(prop)) == .@"enum") @intFromEnum(prop) else prop.value).?)) orelse ((if (@typeInfo(@TypeOf(prop)) == .@"enum") @intFromEnum(prop) else prop.value).?.toEmpty())), p.allocator);
            }
            if (result.isMissing()) {
                return null;
            }
            return result;
},
.e_array => {
var items = expr.data.e_array.items.slice();
            _ = &items;
            for (cp_iter_slice(items)) |item| {
                _ = &item;
                if ((item.data == .e_spread)) {
                    var end: usize = 0;
                    _ = &end;
                    for (cp_iter_slice(items)) |item_| {
                        _ = &item_;
                        if ((item_.data != .e_missing)) {
                            items[cp_cast_int(usize, end)] = item_;
                            end = (end + 1);
                        }
                    }
                    _ = expr.data.e_array.items.shrinkRetainingCapacity(end);
                    return expr;
                }
            }
            return Expr.joinAllWithCommaCallback(items, @TypeOf(p), p, (comptime simplifyUnusedExpr), p.allocator);
},
else => {

},
}
            return expr;
    }

pub fn simplifyUnusedBinaryCommaExpr(p: anytype, expr: Expr) ?Expr {
            if (Environment.allow_assert) {
                _ = assert((expr.data == .e_binary));
                _ = assert((switch (expr.data.e_binary.op) {
.bin_strict_eq, .bin_strict_ne, .bin_comma => true,
else => false,
}));
            }
            const stack: *std.array_list.Managed(BinaryExpressionSimplifyVisitor) = (&p.binary_expression_simplify_stack);
            const stack_bottom = stack.items.len;
            defer {
            _ = stack.shrinkRetainingCapacity(stack_bottom);
            }
            _ = bun.handleOom(stack.append(.{ .bin = expr.data.e_binary }));
            var left: Expr = expr.data.e_binary.left;
            _ = &left;
            while (left.data.@"as"(.e_binary)) |left_bin| {
                switch (left_bin.op) {
.bin_strict_eq, .bin_strict_ne, .bin_comma => {
_ = bun.handleOom(stack.append(.{ .bin = left_bin }));
                left = left_bin.left;
},
else => {
break;
},
}
            }
            var i = stack.items.len;
            _ = &i;
            var result = ((SideEffects.simplifyUnusedExpr(p, left)) orelse (Expr.empty));
            _ = &result;
            while ((i > stack_bottom)) {
                i = (i - 1);
                const top = stack.items[@as(usize, @intCast(i))];
                const visited_right = ((SideEffects.simplifyUnusedExpr(p, top.bin.right)) orelse (Expr.empty));
                result = result.joinWithComma(visited_right, p.allocator);
            }
            return (if (result.isMissing()) null else result);
    }

pub fn findIdentifiers(binding: Binding, decls: *std.array_list.Managed(G.Decl)) void {
            switch (binding.data) {
.b_identifier => {
_ = ((decls.append(.{ .binding = binding })) catch unreachable);
},
.b_array => |array| {
for (array.items) |item| {
                _ = &item;
                _ = SideEffects.findIdentifiers(item.binding, decls);
            }
},
.b_object => |obj| {
for (cp_iter_slice(obj.properties)) |item| {
                _ = &item;
                _ = SideEffects.findIdentifiers((if (@typeInfo(@TypeOf(item)) == .@"enum") @intFromEnum(item) else item.value), decls);
            }
},
else => {

},
}
    }

pub fn shouldKeepStmtsInDeadControlFlow(stmts: []Stmt, allocator: Allocator) bool {
            for (cp_iter_slice(stmts)) |child| {
                _ = &child;
                if (SideEffects.shouldKeepStmtInDeadControlFlow(child, allocator)) {
                    return true;
                }
            }
            return false;
    }

pub fn shouldKeepStmtInDeadControlFlow(stmt: Stmt, allocator: Allocator) bool {
            switch (stmt.data) {
.s_empty, .s_expr, .s_throw, .s_return, .s_break, .s_continue, .s_class, .s_debugger => {
return false;
},
.s_local => |local| {
if ((local.kind != .k_var)) {
                return false;
            }
            if (((local.decls.len == 1) and (local.decls.ptr[0].binding.data == .b_identifier))) {
                const prev = local.decls.ptr[0];
                stmt.data.s_local.decls.ptr[cp_cast_int(usize, 0)] = G.Decl{ .binding = prev.binding };
                return true;
            }
            var decls = ((std.array_list.Managed(G.Decl).initCapacity(allocator, local.decls.len)) catch unreachable);
            _ = &decls;
            for (cp_iter_slice(local.decls.slice())) |decl| {
                _ = &decl;
                _ = SideEffects.findIdentifiers(decl.binding, (&decls));
            }
            local.decls = .moveFromList((&decls));
            return true;
},
.s_block => |block| {
return SideEffects.shouldKeepStmtsInDeadControlFlow(block.stmts, allocator);
},
.s_try => |try_stmt| {
if (SideEffects.shouldKeepStmtsInDeadControlFlow(try_stmt.body, allocator)) {
                return true;
            }
            if (try_stmt.catch_) |*catch_stmt| {
                _ = &catch_stmt;
                if (SideEffects.shouldKeepStmtsInDeadControlFlow((catch_stmt.*).body, allocator)) {
                    return true;
                }
            }
            if (try_stmt.finally) |*finally_stmt| {
                _ = &finally_stmt;
                if (SideEffects.shouldKeepStmtsInDeadControlFlow((finally_stmt.*).stmts, allocator)) {
                    return true;
                }
            }
            return false;
},
.s_if => |_if_| {
if (SideEffects.shouldKeepStmtInDeadControlFlow(_if_.yes, allocator)) {
                return true;
            }
            const no = ((_if_.no) orelse { return false; });
            return SideEffects.shouldKeepStmtInDeadControlFlow(no, allocator);
},
.s_while => {
return SideEffects.shouldKeepStmtInDeadControlFlow(stmt.data.s_while.body, allocator);
},
.s_do_while => {
return SideEffects.shouldKeepStmtInDeadControlFlow(stmt.data.s_do_while.body, allocator);
},
.s_for => |__for__| {
if (__for__.init) |init_| {
                _ = &init_;
                if (SideEffects.shouldKeepStmtInDeadControlFlow(init_, allocator)) {
                    return true;
                }
            }
            return SideEffects.shouldKeepStmtInDeadControlFlow(__for__.body, allocator);
},
.s_for_in => |__for__| {
return (SideEffects.shouldKeepStmtInDeadControlFlow(__for__.init, allocator) or SideEffects.shouldKeepStmtInDeadControlFlow(__for__.body, allocator));
},
.s_for_of => |__for__| {
return (SideEffects.shouldKeepStmtInDeadControlFlow(__for__.init, allocator) or SideEffects.shouldKeepStmtInDeadControlFlow(__for__.body, allocator));
},
.s_label => |label| {
return SideEffects.shouldKeepStmtInDeadControlFlow(label.stmt, allocator);
},
else => {
return true;
},
}
    }

pub fn isPrimitiveWithSideEffects(data: Expr.Data) bool {
            switch (data) {
.e_null, .e_undefined, .e_boolean, .e_branch_boolean, .e_number, .e_big_int, .e_string, .e_inlined_enum => {
return true;
},
.e_unary => |e| {
switch (e.op) {
.un_pos, .un_neg, .un_cpl, .un_pre_dec, .un_pre_inc, .un_post_dec, .un_post_inc, .un_not, .un_delete, .un_void, .un_typeof => {
return true;
},
else => {

},
}
},
.e_binary => |e| {
switch (e.op) {
.bin_lt, .bin_le, .bin_gt, .bin_ge, .bin_in, .bin_instanceof, .bin_loose_eq, .bin_loose_ne, .bin_strict_eq, .bin_strict_ne, .bin_add, .bin_add_assign, .bin_sub, .bin_mul, .bin_div, .bin_rem, .bin_pow, .bin_sub_assign, .bin_mul_assign, .bin_div_assign, .bin_rem_assign, .bin_pow_assign, .bin_shl, .bin_shr, .bin_u_shr, .bin_shl_assign, .bin_shr_assign, .bin_u_shr_assign, .bin_bitwise_or, .bin_bitwise_and, .bin_bitwise_xor, .bin_bitwise_or_assign, .bin_bitwise_and_assign, .bin_bitwise_xor_assign => {
return true;
},
.bin_logical_and, .bin_logical_or, .bin_nullish_coalescing, .bin_logical_and_assign, .bin_logical_or_assign, .bin_nullish_coalescing_assign => {
return (SideEffects.isPrimitiveWithSideEffects(e.left.data) and SideEffects.isPrimitiveWithSideEffects(e.right.data));
},
.bin_comma => {
return SideEffects.isPrimitiveWithSideEffects(e.right.data);
},
else => {

},
}
},
.e_if => |e| {
return (SideEffects.isPrimitiveWithSideEffects(e.yes.data) and SideEffects.isPrimitiveWithSideEffects(e.no.data));
},
else => {

},
}
            return false;
    }

pub fn toNullOrUndefined(p: anytype, exp: Expr.Data) Result {
            if ((!p.options.features.dead_code_elimination)) {
                return Result{ .ok = false, .value = undefined, .side_effects = .could_have_side_effects };
            }
            switch (exp) {
.e_boolean, .e_branch_boolean, .e_number, .e_string, .e_reg_exp, .e_function, .e_arrow, .e_big_int => {
return Result{ .value = false, .side_effects = .no_side_effects, .ok = true };
},
.e_object, .e_array, .e_class => {
return Result{ .value = false, .side_effects = .could_have_side_effects, .ok = true };
},
.e_null, .e_undefined => {
return Result{ .value = true, .side_effects = .no_side_effects, .ok = true };
},
.e_unary => |e| {
switch (e.op) {
.un_pos, .un_neg, .un_cpl, .un_pre_dec, .un_pre_inc, .un_post_dec, .un_post_inc, .un_not, .un_typeof, .un_delete => {
return Result{ .ok = true, .value = false, .side_effects = SideEffects.could_have_side_effects };
},
.un_void => {
return Result{ .value = true, .side_effects = .could_have_side_effects, .ok = true };
},
else => {

},
}
},
.e_binary => |e| {
switch (e.op) {
.bin_add, .bin_add_assign, .bin_sub, .bin_mul, .bin_div, .bin_rem, .bin_pow, .bin_sub_assign, .bin_mul_assign, .bin_div_assign, .bin_rem_assign, .bin_pow_assign, .bin_shl, .bin_shr, .bin_u_shr, .bin_shl_assign, .bin_shr_assign, .bin_u_shr_assign, .bin_bitwise_or, .bin_bitwise_and, .bin_bitwise_xor, .bin_bitwise_or_assign, .bin_bitwise_and_assign, .bin_bitwise_xor_assign, .bin_lt, .bin_le, .bin_gt, .bin_ge, .bin_in, .bin_instanceof, .bin_loose_eq, .bin_loose_ne, .bin_strict_eq, .bin_strict_ne => {
return Result{ .ok = true, .value = false, .side_effects = SideEffects.could_have_side_effects };
},
.bin_comma => {
const res = SideEffects.toNullOrUndefined(p, e.right.data);
            if (res.ok) {
                return Result{ .ok = true, .value = (if (@typeInfo(@TypeOf(res)) == .@"enum") @intFromEnum(res) else res.value), .side_effects = SideEffects.could_have_side_effects };
            }
},
else => {

},
}
},
.e_inlined_enum => |inlined| {
return SideEffects.toNullOrUndefined(p, (if (@typeInfo(@TypeOf(inlined)) == .@"enum") @intFromEnum(inlined) else inlined.value).data);
},
else => {

},
}
            return Result{ .ok = false, .value = false, .side_effects = SideEffects.could_have_side_effects };
    }

pub fn toBoolean(p: anytype, exp: Expr.Data) Result {
            if ((!p.options.features.dead_code_elimination)) {
                return Result{ .ok = false, .value = undefined, .side_effects = .could_have_side_effects };
            }
            return SideEffects.toBooleanWithoutDCECheck(exp);
    }

pub fn toBooleanWithoutDCECheck(exp: Expr.Data) Result {
            switch (exp) {
.e_null, .e_undefined => {
return Result{ .ok = true, .value = false, .side_effects = .no_side_effects };
},
.e_boolean, .e_branch_boolean => |e| {
return Result{ .ok = true, .value = (if (@typeInfo(@TypeOf(e)) == .@"enum") @intFromEnum(e) else e.value), .side_effects = .no_side_effects };
},
.e_number => |e| {
return Result{ .ok = true, .value = (((if (@typeInfo(@TypeOf(e)) == .@"enum") @intFromEnum(e) else e.value) != 0.0) and (!std.math.isNan((if (@typeInfo(@TypeOf(e)) == .@"enum") @intFromEnum(e) else e.value)))), .side_effects = .no_side_effects };
},
.e_big_int => |e| {
return Result{ .ok = true, .value = (!strings.eqlComptime((if (@typeInfo(@TypeOf(e)) == .@"enum") @intFromEnum(e) else e.value), "0")), .side_effects = .no_side_effects };
},
.e_string => |e| {
return Result{ .ok = true, .value = e.isPresent(), .side_effects = .no_side_effects };
},
.e_function, .e_arrow, .e_reg_exp => {
return Result{ .ok = true, .value = true, .side_effects = .no_side_effects };
},
.e_object, .e_array, .e_class => {
return Result{ .ok = true, .value = true, .side_effects = .could_have_side_effects };
},
.e_unary => |e_| {
switch (e_.op) {
.un_void => {
return Result{ .ok = true, .value = false, .side_effects = .could_have_side_effects };
},
.un_typeof => {
return Result{ .ok = true, .value = true, .side_effects = .could_have_side_effects };
},
.un_not => {
const result = SideEffects.toBooleanWithoutDCECheck((if (@typeInfo(@TypeOf(e_)) == .@"enum") @intFromEnum(e_) else e_.value).data);
            if (result.ok) {
                return .{ .ok = true, .value = (!(if (@typeInfo(@TypeOf(result)) == .@"enum") @intFromEnum(result) else result.value)), .side_effects = result.side_effects };
            }
},
else => {

},
}
},
.e_binary => |e_| {
switch (e_.op) {
.bin_logical_or => {
const result = SideEffects.toBooleanWithoutDCECheck(e_.right.data);
            if (((if (@typeInfo(@TypeOf(result)) == .@"enum") @intFromEnum(result) else result.value) and result.ok)) {
                return Result{ .ok = true, .value = true, .side_effects = .could_have_side_effects };
            }
},
.bin_logical_and => {
const result = SideEffects.toBooleanWithoutDCECheck(e_.right.data);
            if (((!(if (@typeInfo(@TypeOf(result)) == .@"enum") @intFromEnum(result) else result.value)) and result.ok)) {
                return Result{ .ok = true, .value = false, .side_effects = .could_have_side_effects };
            }
},
.bin_comma => {
var result = SideEffects.toBooleanWithoutDCECheck(e_.right.data);
            _ = &result;
            if (result.ok) {
                result.side_effects = .could_have_side_effects;
                return result;
            }
},
.bin_gt => {
if (e_.left.data.toFiniteNumber()) |left_num| {
                _ = &left_num;
                if (e_.right.data.toFiniteNumber()) |right_num| {
                    _ = &right_num;
                    return Result{ .ok = true, .value = (left_num > right_num), .side_effects = .no_side_effects };
                }
            }
},
.bin_lt => {
if (e_.left.data.toFiniteNumber()) |left_num| {
                _ = &left_num;
                if (e_.right.data.toFiniteNumber()) |right_num| {
                    _ = &right_num;
                    return Result{ .ok = true, .value = (left_num < right_num), .side_effects = .no_side_effects };
                }
            }
},
.bin_le => {
if (e_.left.data.toFiniteNumber()) |left_num| {
                _ = &left_num;
                if (e_.right.data.toFiniteNumber()) |right_num| {
                    _ = &right_num;
                    return Result{ .ok = true, .value = (left_num <= right_num), .side_effects = .no_side_effects };
                }
            }
},
.bin_ge => {
if (e_.left.data.toFiniteNumber()) |left_num| {
                _ = &left_num;
                if (e_.right.data.toFiniteNumber()) |right_num| {
                    _ = &right_num;
                    return Result{ .ok = true, .value = (left_num >= right_num), .side_effects = .no_side_effects };
                }
            }
},
else => {

},
}
},
.e_inlined_enum => |inlined| {
return SideEffects.toBooleanWithoutDCECheck((if (@typeInfo(@TypeOf(inlined)) == .@"enum") @intFromEnum(inlined) else inlined.value).data);
},
.e_special => |special| {
switch (special) {
.module_exports, .resolved_specifier_string, .hot_data => {

},
.hot_accept, .hot_accept_visited, .hot_enabled => {
return .{ .ok = true, .value = true, .side_effects = .no_side_effects };
},
.hot_disabled => {
return .{ .ok = true, .value = false, .side_effects = .no_side_effects };
},
}
},
else => {

},
}
            return Result{ .ok = false, .value = false, .side_effects = SideEffects.could_have_side_effects };
    }
    
    pub const Result = SideEffectsResult;
    
    pub const BinaryExpressionSimplifyVisitor = SideEffectsBinaryExpressionSimplifyVisitor;
    
    pub const toNumber = Expr.Data.toNumber;
    
    pub const typeof = Expr.Data.toTypeof;
    
    pub const toTypeOf = Expr.Data.typeof;
};

pub const SideEffectsResult = struct {
    side_effects: SideEffects,
    ok: bool = false,
    value: bool = false,
};

pub const SideEffectsBinaryExpressionSimplifyVisitor = struct {
    bin: *E.Binary,
};

